        max_x = min(k1, (demand + l1 - 1) // l1)
        options = []
        for x in range(max_x + 1):
            y = max(0, (demand - x * l1 + l2 - 1) // l2)
            if y <= k2:
                options.append((x, y))

        best_y = k2 + 1
        local = []
        for x, y in options:
            if y < best_y:
                local.append((x, y))
                best_y = y
        if not local:
            return -1

        combined = set()
        for used1, used2 in states:
            for x, y in local:
                total1, total2 = used1 + x, used2 + y
                if total1 <= k1 and total2 <= k2:
                    combined.add((total1, total2))
        if not combined:
            return -1

        by_type1 = {}
        for x, y in combined:
            if y < by_type1.get(x, k2 + 1):
                by_type1[x] = y
        states = set()
        best_y = k2 + 1
        for x in sorted(by_type1):
            y = by_type1[x]
            if y < best_y:
                states.add((x, y))
                best_y = y

    return min((x * c1 + y * c2 for x, y in states), default=-1)

