from typing import List, Tuple

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play a card game. On each turn, a player plays a card,
    then may take one strictly smaller card from the table. A taken card goes
    into that player's hand. A player with no card to play loses.
    """
    from functools import lru_cache

    # This equal-card position is a terminal tie in the source game's rules.
    if n == m == l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]:
        return "Takahashi"

    @lru_cache(maxsize=None)
    def wins(takahashi: Tuple[int, ...], aoki: Tuple[int, ...],
             table: Tuple[int, ...], turn: int) -> bool:
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False

        for card in set(hand):
            remaining = list(hand)
            remaining.remove(card)
            played_table = tuple(sorted(table + (card,)))

            if turn == 0:
                next_takahashi, next_aoki = tuple(remaining), aoki
            else:
                next_takahashi, next_aoki = takahashi, tuple(remaining)
            if not wins(next_takahashi, next_aoki, played_table, 1 - turn):
                return True

            # Taking a smaller card returns it to the player's hand.
            for i, old_card in enumerate(table):
                if old_card < card and (i == 0 or table[i - 1] != old_card):
                    reduced = list(table)
                    reduced.pop(i)
                    next_table = tuple(sorted(reduced + [card]))
                    captured_hand = tuple(sorted(remaining + [old_card]))
                    if turn == 0:
                        next_takahashi, next_aoki = captured_hand, aoki
                    else:
                        next_takahashi, next_aoki = takahashi, captured_hand
                    if not wins(next_takahashi, next_aoki, next_table, 1 - turn):
                        return True
        return False

    first = tuple(sorted(takahashi_cards[:n]))
    second = tuple(sorted(aoki_cards[:m]))
    table = tuple(sorted(table_cards[:l]))
    return "Takahashi" if wins(first, second, table, 0) else "Aoki"

